import XCTest
@testable import Core
final class EvaartaTaskWorkOperatingSystemTests:XCTestCase{
 func testPhasesAtoE(){let t=EvaartaWorkTask(id:"t1",title:"Report",projectId:"p1",skills:["research"],estimateMinutes:120);let c=EvaartaCandidate(id:"u1",skills:["research"],capacityMinutes:480,committedMinutes:120,projectIds:["p1"]);let a=EvaartaTaskWorkOperatingSystem.assign(t,c);XCTAssertEqual(a.status,"offered");XCTAssertEqual(EvaartaTaskWorkOperatingSystem.recommend(a,[c]).first?.0,"u1");XCTAssertEqual(EvaartaTaskWorkOperatingSystem.monitor(a).health,"unaccepted");let t2=EvaartaWorkTask(id:"t2",title:"Review",dependsOn:["t1"]);XCTAssertTrue(EvaartaTaskWorkOperatingSystem.validateGraph([a,t2]));XCTAssertEqual(EvaartaTaskWorkOperatingSystem.impact([a,t2],"t1"),Set(["t2"]));XCTAssertEqual(EvaartaTaskWorkOperatingSystem.projectHealth([t2]),"at-risk");XCTAssertEqual(EvaartaTaskWorkOperatingSystem.verify(EvaartaWorkTask(id:"t3",title:"Verify",evidenceIds:["e1"])).status,"verified")}}
